keys=sorted(set(map(key,names)))
F=np.column_stack([R[:,[key(n)==k for n in names]].mean(1) for k in keys])
S=np.cov(F.T); S=0.5*S+0.5*np.diag(np.diag(S)); mv=np.linalg.solve(S,F.mean(0))
C['fam_mv']=famw(dict(zip(keys,mv/np.abs(mv).sum())))
